import{R as t,e as a,f as o,U as i}from"./chunks/framework.ywem4qy5.js";const m=JSON.parse('{"title":"Template Overrides","description":"","frontmatter":{},"headers":[],"relativePath":"theming/template-overrides.md","filePath":"theming/template-overrides.md","lastUpdated":1777204343000}'),d={name:"theming/template-overrides.md"};function l(r,e,s,c,n,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="template-overrides" tabindex="-1">Template Overrides <a class="header-anchor" href="#template-overrides" aria-label="Permalink to &quot;Template Overrides&quot;">​</a></h1><p>While Formie&#39;s default templates suit most needs, you can of course roll your own templates, so you have total control over the form, field, layout and more.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Read <a href="/theming/overview">Theming Overview</a> first if you want to compare template overrides with the other theming options.</p></div><p>The great thing about Formie&#39;s custom templates is that it doesn&#39;t have to be all-or-nothing. You can choose to override a single template, or all. For instance, you might have very specific markup needs to a Dropdown field. You can override just the template for the dropdown field, and nothing else.</p><h2 id="form-templates" tabindex="-1">Form Templates <a class="header-anchor" href="#form-templates" aria-label="Permalink to &quot;Form Templates&quot;">​</a></h2><p>To get started, navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Form Templates</strong> and create a new template. Enable the <strong>Use Custom Template</strong> setting to be able to define a template directory for your custom templates to sit. For example, if your templates exist in <code>templates/_forms</code>, you would enter <code>_forms</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Be sure to select a <em>directory</em> when setting the template path, as there are multiple templates Formie can override. You can look at the <a href="https://github.com/verbb/formie/tree/craft-5/src/templates/_special/form-template" target="_blank" rel="noreferrer">directory structure</a> for more.</p></div><p>You can also use the <strong>Copy Templates</strong> setting when creating, which will copy all of Formie&#39;s default templates into the directory you&#39;ve specified. That way, you&#39;re starting off with the templates Formie already uses as a basis for your custom templates.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can&#39;t modify Formie&#39;s default Form Templates. Instead, you must create a new Form Template, and ensure your forms use that. This gives you the benefit of being able to easily manage <em>multiple</em> custom templates across your forms.</p></div><p>Before we dive in, it&#39;s worth taking the time to understand the structure of how templates go together.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>We&#39;re using the <code>.html</code> extension here for clarity. You can use <code>.twig</code> or whatever you have set in your <a href="https://craftcms.com/docs/4.x/config/config-settings.html#defaulttemplateextensions" target="_blank" rel="noreferrer">defaultTemplateExtensions</a> for the actual files.</p></div><ul><li><code>form.html</code></li><li><code>field.html</code></li><li><code>page.html</code></li><li><code>form/</code><ul><li><code>body.html</code></li><li><code>footer.html</code></li><li><code>header.html</code></li><li><code>hidden-inputs.html</code></li><li><code>navigation.html</code></li><li><code>progress.html</code></li><li><code>tabs.html</code></li><li><code>...</code></li></ul></li><li><code>page/</code><ul><li><code>body.html</code></li><li><code>buttons.html</code></li><li><code>captchas.html</code></li><li><code>footer.html</code></li><li><code>header.html</code></li></ul></li><li><code>field/</code><ul><li><code>errors.html</code></li><li><code>instructions.html</code></li><li><code>label.html</code></li></ul></li><li><code>fields/</code><ul><li><code>address.html</code></li><li><code>agree.html</code></li><li><code>categories.html</code></li><li><code>date/</code><ul><li><code>_calendar.html</code></li><li><code>_datePicker.html</code></li><li><code>...</code></li></ul></li><li><code>group/</code><ul><li><code>_row.html</code></li><li><code>index.html</code></li></ul></li><li><code>name/</code><ul><li><code>_multiple.html</code></li><li><code>_single.html</code></li><li><code>index.html</code></li></ul></li><li><code>repeater/</code><ul><li><code>_row.html</code></li><li><code>index.html</code></li></ul></li><li><code>table/</code><ul><li><code>_row.html</code></li><li><code>index.html</code></li></ul></li><li><code>...</code></li></ul></li></ul><p>Let&#39;s start with the top-level templates.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Check out the raw templates on <a href="https://github.com/verbb/formie/tree/craft-5/src/templates/_special" target="_blank" rel="noreferrer">Formie&#39;s GitHub</a> - they&#39;ll be the most up to date.</p></div><h2 id="overriding-form-templates" tabindex="-1">Overriding Form Templates <a class="header-anchor" href="#overriding-form-templates" aria-label="Permalink to &quot;Overriding Form Templates&quot;">​</a></h2><p>To override the form template, provide a file named <code>form.html</code> in your template directory.</p><h3 id="available-template-variables" tabindex="-1">Available Template Variables <a class="header-anchor" href="#available-template-variables" aria-label="Permalink to &quot;Available Template Variables&quot;">​</a></h3><p>These templates have access to the following variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>form</code></td><td>A <a href="/reference/form">Form</a> object, for the form instance this template is for.</td></tr><tr><td><code>submission</code></td><td>The current <a href="/reference/submission">Submission</a> object this form may or may not have.</td></tr><tr><td><code>renderOptions</code></td><td>A collection of <a href="/templates/render-options">Render Options</a>.</td></tr></tbody></table><h2 id="overriding-page-templates" tabindex="-1">Overriding Page Templates <a class="header-anchor" href="#overriding-page-templates" aria-label="Permalink to &quot;Overriding Page Templates&quot;">​</a></h2><p>To override the page template, provide a file named <code>page.html</code> in your template directory.</p><h3 id="available-template-variables-1" tabindex="-1">Available Template Variables <a class="header-anchor" href="#available-template-variables-1" aria-label="Permalink to &quot;Available Template Variables&quot;">​</a></h3><p>These templates have access to the following variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>form</code></td><td>A <a href="/reference/form">Form</a> object that this field belongs to.</td></tr><tr><td><code>page</code></td><td>A <a href="/reference/page">Page</a> object, for the page instance this template is for.</td></tr><tr><td><code>renderOptions</code></td><td>A collection of <a href="/templates/render-options">Render Options</a>.</td></tr></tbody></table><h2 id="overriding-field-wrapper-templates" tabindex="-1">Overriding Field Wrapper Templates <a class="header-anchor" href="#overriding-field-wrapper-templates" aria-label="Permalink to &quot;Overriding Field Wrapper Templates&quot;">​</a></h2><p>To override the field template, provide a file named <code>field.html</code> in your template directory. This is the wrapper template around all fields. You can also override individual field types&#39; templates, rather than changing the template for every field, regardless of type.</p><h3 id="available-template-variables-2" tabindex="-1">Available Template Variables <a class="header-anchor" href="#available-template-variables-2" aria-label="Permalink to &quot;Available Template Variables&quot;">​</a></h3><p>These templates have access to the following variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>form</code></td><td>A <a href="/reference/form">Form</a> object that this field belongs to.</td></tr><tr><td><code>field</code></td><td>A <a href="/reference/field">Field</a> object, for the field instance this template is for.</td></tr><tr><td><code>handle</code></td><td>The handle of the field.</td></tr><tr><td><code>element</code></td><td>The current <a href="/reference/submission">Submission</a> object this form may or may not have.</td></tr><tr><td><code>renderOptions</code></td><td>A collection of <a href="/templates/render-options">Render Options</a>.</td></tr></tbody></table><h2 id="overriding-field-templates" tabindex="-1">Overriding Field Templates <a class="header-anchor" href="#overriding-field-templates" aria-label="Permalink to &quot;Overriding Field Templates&quot;">​</a></h2><p>You&#39;ll notice the above structure includes the <code>fields/</code> directory. Inside this directory are a mixture of folders and individual files, each representing a template that you&#39;re able to override.</p><p>First, you&#39;ll need to identify the template&#39;s name. It&#39;s derived from the PHP class name for the field, converted to a &quot;kebab&quot; string. For easy reference, you can use the below table.</p><table tabindex="0"><thead><tr><th>Class Name</th><th>Template</th></tr></thead><tbody><tr><td><code>Address</code></td><td><code>address.html</code></td></tr><tr><td><code>Agree</code></td><td><code>agree.html</code></td></tr><tr><td><code>Calculations</code></td><td><code>calculations.html</code></td></tr><tr><td><code>Categories</code></td><td><code>categories.html</code></td></tr><tr><td><code>Checkboxes</code></td><td><code>checkboxes.html</code></td></tr><tr><td><code>Date</code></td><td><code>date.html</code></td></tr><tr><td><code>Dropdown</code></td><td><code>dropdown.html</code></td></tr><tr><td><code>Email</code></td><td><code>email.html</code></td></tr><tr><td><code>Entries</code></td><td><code>entries.html</code></td></tr><tr><td><code>FileUpload</code></td><td><code>file-upload.html</code></td></tr><tr><td><code>Forms</code></td><td><code>forms.html</code></td></tr><tr><td><code>Group</code></td><td><code>group/index.html</code></td></tr><tr><td><code>Heading</code></td><td><code>heading.html</code></td></tr><tr><td><code>Hidden</code></td><td><code>hidden.html</code></td></tr><tr><td><code>Html</code></td><td><code>html.html</code></td></tr><tr><td><code>MultiLineText</code></td><td><code>multi-line-text.html</code></td></tr><tr><td><code>Name</code></td><td><code>name/index.html</code></td></tr><tr><td><code>Number</code></td><td><code>number.html</code></td></tr><tr><td><code>Password</code></td><td><code>password.html</code></td></tr><tr><td><code>Payment</code></td><td><code>payment.html</code></td></tr><tr><td><code>Phone</code></td><td><code>phone.html</code></td></tr><tr><td><code>Products</code></td><td><code>products.html</code></td></tr><tr><td><code>Radio</code></td><td><code>radio.html</code></td></tr><tr><td><code>Recipients</code></td><td><code>recipients.html</code></td></tr><tr><td><code>Repeater</code></td><td><code>repeater/index.html</code></td></tr><tr><td><code>Section</code></td><td><code>section.html</code></td></tr><tr><td><code>Signature</code></td><td><code>signature.html</code></td></tr><tr><td><code>SingleLineText</code></td><td><code>single-line-text.html</code></td></tr><tr><td><code>Submissions</code></td><td><code>submissions.html</code></td></tr><tr><td><code>Summary</code></td><td><code>summary.html</code></td></tr><tr><td><code>Table</code></td><td><code>table/index.html</code></td></tr><tr><td><code>Tags</code></td><td><code>tags.html</code></td></tr><tr><td><code>Users</code></td><td><code>users.html</code></td></tr><tr><td><code>Variants</code></td><td><code>variants.html</code></td></tr></tbody></table><p>Adding a template file in your specified template directory will use that template file over the ones Formie provide.</p><p>You might also have noticed we&#39;ve shown <code>date</code> in a folder. Due to how Twig resolves templates, the below are equivalent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fields/date.html - Is the same as - fields/date/index.html</span></span></code></pre></div><p>For complex fields that have multiple templates, we&#39;ve used folders to organise multiple templates in a single folder. You&#39;re welcome to follow this same pattern, but you&#39;re not forced to.</p><p>For example, the Date field, has the following templates in a folder:</p><ul><li><code>fields/date/_calendar.html</code></li><li><code>fields/date/_datepicker.html</code></li><li><code>fields/date/_dropdowns.html</code></li><li><code>fields/date/_inputs.html</code></li><li><code>fields/date/index.html</code></li></ul><p>This is because the date field has many display configurations. If you want to override the templates for this field, you just need to alter the <code>index.html</code> file. You can use the includes (denoted by <code>_</code>), or you don&#39;t have to.</p><h2 id="overriding-partials" tabindex="-1">Overriding Partials <a class="header-anchor" href="#overriding-partials" aria-label="Permalink to &quot;Overriding Partials&quot;">​</a></h2><p>You&#39;ll have noticed in the template structure above that Formie uses partials throughout the form, page, and field templates. This helps keep the markup modular, and it also means you can override just one part of the output without replacing an entire top-level template.</p><p>For example, <code>form.html</code> includes partials like <code>form/navigation.html</code>, <code>form/progress.html</code>, and <code>form/tabs.html</code>. Rather than overriding <code>form.html</code> just to change one of those, you can override the partial directly.</p><p>For example, if you want to change the page navigation for a multi-page form, you can create <code>form/navigation.html</code> in your custom template directory and leave the rest of the form templates alone.</p><h3 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h3><p>Formie&#39;s templates use a custom Twig function for partials:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ formieInclude(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;form/navigation&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>This is different to a normal Twig include such as:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;form/navigation&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><p>The difference is how the partial path is resolved. A regular <code>{% include %}</code> is relative to the current template. <code>formieInclude()</code> checks your override directory first, then falls back to Formie&#39;s default templates.</p><h3 id="example-partial-override" tabindex="-1">Example Partial Override <a class="header-anchor" href="#example-partial-override" aria-label="Permalink to &quot;Example Partial Override&quot;">​</a></h3><p>For example, if you only want to change how field errors are rendered, create <code>field/errors.html</code> in your template directory:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> field.getErrors(element) %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ul</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-field-errors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        {% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> error </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> field.getErrors(element) %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;{{ error }}&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">li</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        {% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endfor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{% </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">endif</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %}</span></span></code></pre></div><p>That will override just the error partial, while leaving the rest of the field template structure in place.</p>`,54)])])}const u=t(d,[["render",l]]);export{m as __pageData,u as default};
